public class Wrappers {
    public static void main(String[] args) {
        Integer a = 100, b = 100;
        System.out.println(a == b);       // true — cached small integers

        Integer c = 200, d = 200;
        System.out.println(c == d);       // false — outside the cache range

        System.out.println(c.equals(d));  // true — correct way to compare

        Integer maybeNull = null;
        // int x = maybeNull;              // NullPointerException on unboxing
    }
}
